/* 删除屏幕根对象会递归删除其子控件；活动屏幕的安全切换由辅助函数处理。 */
void ui_displaydark_screen_destroy(void)
{
    if (aidogui_ui.displaydark.root != NULL) {
        _ui_screen_destroy(&aidogui_ui.displaydark.root);
        aidogui_ui.displaydark.root = NULL;
    }
}

/* 仅用于已离开的屏幕：保留根对象，子控件的 DELETE 回调会清空各自句柄。 */
void ui_displaydark_screen_clean(void)
{
    if (aidogui_ui.displaydark.root == NULL || !lv_obj_is_valid(aidogui_ui.displaydark.root)) return;
    ui_displaydark_content_ready = false;
    ui_displaydark_cleaning = true;
    lv_obj_clean(aidogui_ui.displaydark.root);
    ui_displaydark_cleaning = false;
}

